import requests
from bs4 import BeautifulSoup
import pandas as pd

def task_func(url='http://example.com'):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.ConnectionError:
        raise ConnectionError("url cannot be visited.")
    except requests.exceptions.HTTPError as e:
        raise requests.HTTPError(f"requests fail with code:{response.status_code}")

    soup = BeautifulSoup(response.content, 'html.parser')
    table = soup.find('table')

    if table is None:
        raise ValueError("Fail to read table")

    # Check if the first row contains <th> elements
    header_row = table.find('tr')
    if header_row and header_row.find('th'):
        headers = [th.get_text(strip=True) for th in header_row.find_all('th')]
        rows = table.find_all('tr')[1:]  # Skip the header row
        data = []
        for row in rows:
            cells = row.find_all('td')
            row_data = [cell.get_text(strip=True) for cell in cells]
            if row_data:
                data.append(row_data)
        if not data:
            raise ValueError("Fail to read table")
        df = pd.DataFrame(data, columns=headers)
    else:
        rows = table.find_all('tr')
        data = []
        for row in rows:
            cells = row.find_all('td')
            row_data = [cell.get_text(strip=True) for cell in cells]
            if row_data:
                data.append(row_data)
        if not data:
            raise ValueError("Fail to read table")
        df = pd.DataFrame(data)

    return df

