import re
import nltk
from string import punctuation

def task_func(df):
    try:
        nltk.data.find('tokenizers/punkt')
    except LookupError:
        nltk.download('punkt')

    content = ' '.join(df['Content'].astype(str))
    tokens = nltk.word_tokenize(content)
    words = [token.lower() for token in tokens if token not in punctuation]
    freq_dict = {}
    for word in words:
        freq_dict[word] = freq_dict.get(word, 0) + 1
    return freq_dict

