import json
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, process string values that represent numbers by doubling them,
    and create a Pandas DataFrame from the normalized dictionary.

    Parameters:
    json_str (str): The JSON string to be converted.

    Returns:
    DataFrame: A pandas DataFrame created from the normalized JSON string.
    """
    def process_value(value):
        """
        Process a value by doubling numerical values or converting string representations of numbers.
        """
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, str):
            # Try to parse string as number
            try:
                # Check if it's an integer
                if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                    return int(value) * 2
                # Check if it's a float
                else:
                    return float(value) * 2
            except ValueError:
                return value
        elif isinstance(value, list):
            return [process_value(item) for item in value]
        elif isinstance(value, dict):
            return {k: process_value(v) for k, v in value.items()}
        else:
            return value

    # Load and process the JSON data
    data = json.loads(json_str)
    normalized_data = process_value(data)

    # Create DataFrame
    df = pd.DataFrame(normalized_data)
    return df

import json
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, process numeric values (including string representations),
    and create a Pandas DataFrame from it. Returns an empty DataFrame for invalid or empty input.
    Ensures numeric columns are converted to float type where possible.

    Parameters:
    json_str (str): The JSON string to be converted.

    Returns:
    DataFrame: A pandas DataFrame created from the normalized JSON string, or empty DataFrame if input is invalid.
    """
    # Check for empty input
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    # Check if data is empty
    if not data or (isinstance(data, dict) and not data) or (isinstance(data, list) and not data):
        return pd.DataFrame()

    def normalize_value(value):
        """Normalize a value by doubling numbers and converting string numbers"""
        if isinstance(value, (int, float)):
            return float(value * 2)
        elif isinstance(value, str):
            # Try to parse string as number
            try:
                # Try to convert to float first
                num_val = float(value)
                return float(num_val * 2)
            except ValueError:
                return value
        elif isinstance(value, list):
            return [normalize_value(item) for item in value]
        elif isinstance(value, dict):
            return {k: normalize_value(v) for k, v in value.items()}
        else:
            return value

    # Normalize the data
    normalized_data = normalize_value(data)

    # Create DataFrame
    df = pd.DataFrame(normalized_data)

    # Convert numeric columns to float where possible
    for col in df.columns:
        # Try to convert column to numeric, errors='coerce' will convert non-convertible values to NaN
        numeric_col = pd.to_numeric(df[col], errors='coerce')
        # Only convert if all values could be converted (no NaN introduced except for original NaN values)
        if not numeric_col.isna().any() or (numeric_col.notna().sum() > 0 and 
                                           (df[col].isna().sum() == numeric_col.isna().sum())):
            df[col] = numeric_col.astype(float)

    return df

