from collections import Counter

# Constants
CSV_FILE_PATH = 'match_data.csv'

def create_test_csv(filename, content):
    with open(filename, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerows(content)

def task_func(goals=None, penalties=None, csv_file_path=CSV_FILE_PATH):
    # Initialize with zeros
    counter = Counter({'goals': 0, 'penalties': 0})

    # Add values from the goals dictionary if provided
    if goals is not None:
        for value in goals.values():
            try:
                counter['goals'] += int(value)
            except (ValueError, TypeError):
                pass  # Skip invalid values

    # Add values from the penalties dictionary if provided
    if penalties is not None:
        for value in penalties.values():
            try:
                counter['penalties'] += int(value)
            except (ValueError, TypeError):
                pass  # Skip invalid values

    # Check if CSV file exists and is not empty
    if os.path.exists(csv_file_path) and os.path.getsize(csv_file_path) > 0:
        try:
            with open(csv_file_path, 'r') as f:
                reader = csv.DictReader(f)

                # Check if file has headers
                if reader.fieldnames is None:
                    return counter

                for row in reader:
                    # Safely access and convert 'goals' field with default 0 if missing or invalid
                    try:
                        counter['goals'] += int(row.get('goals', 0))
                    except (ValueError, TypeError):
                        pass  # Treat as 0

                    # Safely access and convert 'penalties' field with default 0 if missing or invalid
                    try:
                        counter['penalties'] += int(row.get('penalties', 0))
                    except (ValueError, TypeError):
                        pass  # Treat as 0

        except (csv.Error, IOError):
            # Handle file reading errors by keeping existing counts
            pass

    return counter

