import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if not task_list or n_tasks <= 0:
        return pd.DataFrame(columns=['Task Name', 'Assigned To', 'Due Date'])

    if seed is not None:
        random.seed(seed)

    sampled_tasks = random.sample(task_list, min(n_tasks, len(task_list)))

    assigned_employees = [random.choice(employees) for _ in sampled_tasks]

    current_time = datetime.now()
    due_dates = [
        datetime.fromtimestamp(current_time.timestamp() + random.randint(1, 30) * 86400)
        for _ in sampled_tasks
    ]

    return pd.DataFrame({
        'Task Name': sampled_tasks,
        'Assigned To': assigned_employees,
        'Due Date': due_dates
    })

