import requests
from lxml import html
import pandas as pd
import sqlite3
import os

def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        if webpage_url.startswith('file://'):
            file_path = webpage_url[7:]
            if not os.path.exists(file_path):
                return 0
            with open(file_path, 'r', encoding='utf-8') as f:
                html_content = f.read()
            tree = html.fromstring(html_content)
            tables = tree.xpath('//table')
            if not tables:
                return 0
            table_element = tables[0]
            rows = table_element.xpath('.//tr')
            row_count = len(rows)
            if row_count == 0:
                return 0
            try:
                df = pd.read_html(file_path)[0]
            except:
                return 0
        else:
            try:
                response = requests.get(webpage_url)
                response.raise_for_status()
            except requests.RequestException as e:
                raise requests.RequestException("there is any issue accessing the URL.") from e
            tree = html.fromstring(response.content)
            tables = tree.xpath('//table')
            if not tables:
                return 0
            table_element = tables[0]
            rows = table_element.xpath('.//tr')
            row_count = len(rows)
            if row_count == 0:
                return 0
            try:
                df = pd.read_html(webpage_url)[0]
            except:
                return 0

        try:
            conn = sqlite3.connect(database_name)
            df.to_sql('my_table', conn, if_exists='replace', index=False)
            conn.close()
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError("there are some error during connecting or writing to db.") from e

        return row_count
    except Exception as e:
        if isinstance(e, (requests.RequestException, sqlite3.DatabaseError)):
            raise
        return 0

