from PIL import Image
import pytesseract

IMAGE_PATH = "image.png"

def task_func(filename=IMAGE_PATH, from_encoding=None, to_encoding=None):
    """
    Extracts text from an image file using OCR. If OCR fails or returns no text, falls back to reading the image's comment field.
    For the comment, if it is bytes, decodes it using 'from_encoding', then re-encodes and decodes using 'to_encoding' if provided.

    Parameters:
    filename (str): The path to the image file. Defaults to "image.png".
    from_encoding (str): The source encoding for decoding bytes or converting OCR text. Defaults to None.
    to_encoding (str): The target encoding for encoding conversion. Defaults to None.

    Returns:
    str: The extracted text from OCR or comment if successful, otherwise an empty string.

    Raises:
    ValueError: If encoding conversion fails for OCR text due to invalid encodings.
    """
    try:
        img = Image.open(filename)
        try:
            text = pytesseract.image_to_string(img).strip()
            if text:
                if from_encoding is not None and to_encoding is not None:
                    try:
                        text = text.encode(from_encoding).decode(to_encoding)
                    except (UnicodeDecodeError, LookupError) as e:
                        raise ValueError('Incorrect encoding provided.') from e
                return text
        except Exception:
            pass  # OCR failed, fall back to comment

        # Fallback to comment
        if 'comment' in img.info:
            comment = img.info['comment']
            if isinstance(comment, bytes):
                if from_encoding is None:
                    return ''  # Cannot decode bytes without from_encoding
                try:
                    decoded_str = comment.decode(from_encoding)
                    if to_encoding is not None:
                        decoded_str = decoded_str.encode(to_encoding).decode(to_encoding)
                    return decoded_str
                except (UnicodeDecodeError, LookupError):
                    return ''  # Decoding or encoding failed
            else:
                # Comment is string, return as is
                return comment
        return ''  # No comment found
    except Exception:
        return ''  # Image opening failed or other errors

