        # First attempt: OCR extraction
        try:
            text = pytesseract.image_to_string(img).strip()
            if text:
                # Apply encoding conversion if both encodings are provided
                if from_encoding is not None and to_encoding is not None:
                    try:
                        text = text.encode(from_encoding).decode(to_encoding)
                    except (UnicodeDecodeError, LookupError) as e:
                        raise ValueError('Incorrect encoding provided.') from e
                return text
        except Exception:
            pass  # OCR failed, fall back to comment

        # Second attempt: Comment extraction
        if 'comment' in img.info:
            comment = img.info['comment']
            if isinstance(comment, bytes):
                # Handle bytes comment with encoding conversion
                if from_encoding is None:
                    return ''  # Cannot decode bytes without from_encoding
                try:
                    decoded_comment = comment.decode(from_encoding)
                    if to_encoding is not None:
                        # Re-encode and decode if to_encoding is provided
                        decoded_comment = decoded_comment.encode(to_encoding).decode(to_encoding)
                    return decoded_comment
                except (UnicodeDecodeError, LookupError):
                    return ''  # Encoding conversion failed for comment
            else:
                # Comment is already a string, return directly
                return comment
        return ''  # No usable text found
    except Exception:
        return ''  # Image opening failed or other errors

