import subprocess
import psutil

def task_func(process_name: str) -> str:
    # Check if any running process matches the given name
    processes_found = []
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            processes_found.append(proc)

    if processes_found:
        # Terminate all found processes
        for proc in processes_found:
            try:
                proc.terminate()
                proc.wait(timeout=3)
            except (psutil.NoSuchProcess, psutil.TimeoutExpired):
                try:
                    proc.kill()
                except psutil.NoSuchProcess:
                    pass

        # Start the process again
        try:
            subprocess.Popen(process_name, shell=True)
        except Exception as e:
            raise RuntimeError(f"Failed to start process '{process_name}': {str(e)}")

        return f'Process found. Restarting {process_name}.'
    else:
        # If not found, start the process
        try:
            subprocess.Popen(process_name, shell=True)
        except Exception as e:
            raise RuntimeError(f"Failed to start process '{process_name}': {str(e)}")

        return f'Process not found. Starting {process_name}.'

