        raise ValueError("missing important key.")

    countries_dict = data['Countries']
    processed_data = []

    for country, population in countries_dict.items():
        if not isinstance(country, str):
            raise ValueError("some entry is invalid")
        if not isinstance(population, (int, float)):
            raise ValueError("some entry is invalid")
        if population < 0:
            raise ValueError("some entry is invalid")

        if isinstance(population, float):
            population = math.floor(population)

        processed_data.append((country, population))

    df = pd.DataFrame(processed_data, columns=['Country', 'Population'])

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    output_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(output_path, index=False)
    except IOError:
        raise IOError("csv cannot be saved")

