from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((server_address, server_port))
    server_socket.listen(5)
    server_socket.setblocking(False)

    inputs = [server_socket]
    outputs = []
    message_queues = {}

    start_time = datetime.now()
    end_time = start_time + timedelta(seconds=run_duration)

    while datetime.now() < end_time:
        timeout = min(1.0, (end_time - datetime.now()).total_seconds())
        if timeout <= 0:
            break

        readable, writable, exceptional = select.select(inputs, outputs, inputs, timeout)

        for s in readable:
            if s is server_socket:
                client_socket, client_address = s.accept()
                client_socket.setblocking(False)
                inputs.append(client_socket)
                message_queues[client_socket] = []
            else:
                data = s.recv(buffer_size)
                if data:
                    current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')
                    response = f"{current_time}: {data.decode()}"
                    message_queues[s].append(response.encode())
                    if s not in outputs:
                        outputs.append(s)
                else:
                    if s in outputs:
                        outputs.remove(s)
                    inputs.remove(s)
                    s.close()
                    del message_queues[s]

        for s in writable:
            try:
                next_msg = message_queues[s].pop(0)
                s.send(next_msg)
            except IndexError:
                outputs.remove(s)
            except Exception:
                if s in outputs:
                    outputs.remove(s)
                if s in inputs:
                    inputs.remove(s)
                s.close()
                del message_queues[s]

        for s in exceptional:
            inputs.remove(s)
            if s in outputs:
                outputs.remove(s)
            s.close()
            del message_queues[s]

    for s in inputs:
        s.close()

    return f"Echo server started on {server_address}:{server_port} and ran for {run_duration} seconds."

