import json
import pandas as pd
import numpy as np

def task_func(input_file="data.json"):
    """
    Reads a list of dictionaries from a JSON file and calculates the mean for each key, ignoring non-numeric values.
    Returns the result as a Pandas DataFrame with keys as the index and a single column 'mean'.

    Parameters:
    input_file (str): Path to the input JSON file. Default is "data.json".

    Returns:
    pd.DataFrame: A DataFrame with keys as index and 'mean' as the only column, containing the mean of numeric values for each key.
    """
    with open(input_file, 'r') as file:
        data = json.load(file)

    if not data:
        return pd.DataFrame(columns=['mean'])

    keys = set()
    for d in data:
        keys.update(d.keys())

    numeric_values = {key: [] for key in keys}

    for d in data:
        for key, value in d.items():
            if isinstance(value, (int, float)):
                numeric_values[key].append(value)

    means = {}
    for key, values in numeric_values.items():
        if values:
            means[key] = np.mean(values)
        else:
            means[key] = np.nan

    result_df = pd.DataFrame.from_dict(means, orient='index', columns=['mean'])
    return result_df

