import numpy as np
import json
import csv

def task_func(input_file, output_file):
    with open(input_file, 'r') as f:
        data = json.load(f)

    keys = set()
    for d in data:
        keys.update(d.keys())

    result_dict = {}
    for key in keys:
        values = []
        for d in data:
            if key in d and isinstance(d[key], (int, float)):
                values.append(d[key])
        if values:
            mean_val = float(np.mean(values))
            median_val = float(np.median(values))
            result_dict[key] = {'mean': mean_val, 'median': median_val}

    # Prepare data for CSV writing
    csv_data = []
    for key, stats in result_dict.items():
        csv_data.append({
            'key': key,
            'mean': stats['mean'],
            'median': stats['median']
        })

    # Write to CSV file
    with open(output_file, 'w', newline='') as f:
        fieldnames = ['key', 'mean', 'median']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(csv_data)

    return result_dict

import numpy as np
import os
import soundfile as sf
import librosa
import matplotlib.pyplot as plt

def task_func(L, M, N, audio_file):
    if not os.path.exists(audio_file):
        raise FileNotFoundError("file does not exist.")

    data, _ = sf.read(audio_file)
    rms_audio = np.sqrt(np.mean(data**2))

    total_elements = M * N
    if len(L) < total_elements:
        L_adjusted = L + [0] * (total_elements - len(L))
    else:
        L_adjusted = L[:total_elements]
    matrix = np.array(L_adjusted).reshape(M, N)

    rms_matrix = np.sqrt(np.mean(matrix**2))
    if rms_matrix == 0:
        if rms_audio == 0:
            scale_factor = 1
        else:
            scale_factor = 0
    else:
        scale_factor = rms_audio / rms_matrix

    normalized_matrix = matrix * scale_factor
    return normalized_matrix

